<?php
/** Slice 7 proof 3 (uploads) — POST /api/v1/upload in one request (201; 409 name_taken until `conflict` says version / keep_both; 413 over 64 MB; the quota; a lock) and the parts through the mirror (start, PUT, finish; resume; missing parts; another's session). */
require __DIR__ . '/lib.php';
$s = seed_texts();
$board = $s['board_root']; $contracts = $s['contracts']; $pol = $s['pol_root'];
$km = mint_key(27, 'Upload key')['token']; $kp = mint_key(26, 'Priya up')['token']; $kb = mint_key(28, 'Bea up')['token'];
$kid = (int) one("SELECT id FROM mcp_access_tokens WHERE label = 'Upload key'");
$f1 = tmpfile_of(2500, 'u1', 'scan-001.bin');

echo "1. One request\n";
$r = api('POST', '/api/v1/upload', $km, ['file' => $f1, 'fields' => ['folder' => $contracts]]);
$j = $r['json'];
ok($r['code'] === 201 && $j['document_id'] > 0 && $j['version_no'] === 1 && $j['new_document'] === true && $j['name'] === 'scan-001.bin', 'POST /upload: 201 {document_id, version_id, version_no 1, name}');
$doc = $j['document_id'];
[$path, ] = blob_of($doc);
ok(is_file($path) && file_get_contents($path) === file_get_contents($f1) && one('SELECT sha256 FROM document_versions WHERE id = :v', ['v' => $j['version_id']]) === hash_file('sha256', $f1), 'the bytes are in the store, the sha256 is theirs');
ok((int) one('SELECT owner_member_id FROM documents WHERE id = :d', ['d' => $doc]) === 27 && (int) one('SELECT folder_id FROM documents WHERE id = :d', ['d' => $doc]) === $contracts, 'owned by the key\'s person, in the folder asked');
$ev = last_event('document.upload');
$a = json_decode($ev['after'], true);
ok($ev['source'] === 'api' && (int) $ev['token_id'] === $kid && (int) $ev['document_id'] === $doc && $a['key_label'] === 'Upload key' && $a['byte_size'] === 2500, 'document.upload is logged api under the key\'s label, with the size');
$r = api('POST', '/api/v1/upload', $km, ['file' => $f1, 'fields' => ['folder' => $contracts]]);
ok($r['code'] === 409 && $r['json']['error']['code'] === 'name_taken' && $r['json']['error']['existing_document_id'] === $doc, 'the same name again: 409 name_taken {existing_document_id}');
ok((int) one('SELECT count(*) FROM documents WHERE folder_id = :f AND lower(name) = :n AND trashed_at IS NULL', ['f' => $contracts, 'n' => 'scan-001.bin']) === 1, '...and nothing was added');
$r = api('POST', '/api/v1/upload', $km, ['file' => $f1, 'fields' => ['folder' => $contracts, 'conflict' => 'refuse']]);
ok($r['code'] === 409, 'conflict=refuse says the same');
$f1b = tmpfile_of(2600, 'u1b', 'scan-001.bin');
$r = api('POST', '/api/v1/upload', $km, ['file' => $f1b, 'fields' => ['folder' => $contracts, 'conflict' => 'version']]);
ok($r['code'] === 201 && $r['json']['document_id'] === $doc && $r['json']['version_no'] === 2 && $r['json']['new_document'] === false, 'conflict=version: 201, version 2 of the same document');
ok((int) one('SELECT version_count FROM documents WHERE id = :d', ['d' => $doc]) === 2 && (int) one('SELECT byte_size FROM documents WHERE id = :d', ['d' => $doc]) === 2600, 'the document is at version 2');
$ev = last_event('document.version');
ok($ev['source'] === 'api' && (int) $ev['document_id'] === $doc, 'document.version is logged api');
$r = api('POST', '/api/v1/upload', $km, ['file' => $f1, 'fields' => ['folder' => $contracts, 'conflict' => 'keep_both']]);
ok($r['code'] === 201 && $r['json']['document_id'] !== $doc && $r['json']['name'] !== 'scan-001.bin' && $r['json']['new_document'] === true, 'conflict=keep_both: 201, a second document named ' . ($r['json']['name'] ?? '?'));
ok(api('POST', '/api/v1/upload', $km, ['file' => $f1, 'fields' => ['folder' => $contracts, 'conflict' => 'overwrite']])['code'] === 422, 'an odd conflict: 422');
$f2 = tmpfile_of(900, 'u2', 'renamed-on-the-way.bin');
$r = api('POST', '/api/v1/upload', $km, ['file' => $f2, 'fields' => ['folder' => $contracts, 'name' => 'Kept name.bin', 'note' => 'from the scanner']]);
ok($r['code'] === 201 && $r['json']['name'] === 'Kept name.bin' && one('SELECT note FROM document_versions WHERE id = :v', ['v' => $r['json']['version_id']]) === 'from the scanner', '`name` and `note` are honoured');
$r = api('POST', '/api/v1/upload', $km, ['file' => $f2, 'fields' => ['folder' => $contracts, 'document' => $doc, 'conflict' => 'version']]);
ok($r['code'] === 201 && $r['json']['document_id'] === $doc && $r['json']['version_no'] === 3, '`document` adds a version to that document (3)');
ok(api('POST', '/api/v1/upload', $km, ['file' => $f2, 'fields' => ['folder' => $board, 'document' => $doc]])['code'] === 422, '...but not from another folder: 422');
$dup = tmpfile_of(2500, 'u1', 'same-bytes.bin');
$r = api('POST', '/api/v1/upload', $km, ['file' => $dup, 'fields' => ['folder' => $contracts]]);
ok($r['code'] === 201 && $r['json']['deduplicated'] === true, 'the same bytes under another name are de-duplicated');

echo "2. Refusals\n";
ok(api('POST', '/api/v1/upload', $km, ['fields' => ['folder' => $contracts], 'file' => $f1, 'field' => 'other'])['code'] === 422, 'no field named file: 422');
ok(api('POST', '/api/v1/upload', $km, ['file' => $f1, 'fields' => []])['code'] === 404, 'no folder: 404');
ok(api('POST', '/api/v1/upload', $km, ['file' => $f1, 'fields' => ['folder' => root_of(26)]])['code'] === 404, 'a folder Marco cannot see: 404');
ok(api('POST', '/api/v1/upload', $kb, ['file' => $f1, 'fields' => ['folder' => $contracts]])['code'] === 404, 'Bea cannot see the Board: 404');
$r = api('POST', '/api/v1/upload', $kb, ['file' => tmpfile_of(300, 'b', 'bea.bin'), 'fields' => ['folder' => $pol]]);
ok($r['code'] === 403 && str_contains($r['json']['error']['message'], 'You may not'), 'a folder seen at view only: 403 in words');
ok(api('POST', '/api/v1/upload', null, ['file' => $f1, 'fields' => ['folder' => $contracts]])['code'] === 401, 'no key: 401');
ok(api('GET', '/api/v1/upload', $km)['code'] === 405, 'GET /upload: 405');
$e = tmpfile_of(0, 'e', 'empty.bin');
$r = api('POST', '/api/v1/upload', $km, ['file' => $e, 'fields' => ['folder' => $contracts]]);
ok($r['code'] === 422 && $r['json']['error']['code'] === 'empty', 'an empty file: 422 empty');
$big = tmpfile_of(65 * 1048576, 'big', 'toobig.bin');
$r = api('POST', '/api/v1/upload', $km, ['file' => $big, 'fields' => ['folder' => $contracts]]);
ok($r['code'] === 413 && $r['json']['error']['code'] === 'too_large' && str_contains($r['json']['error']['message'], 'parts'), 'over 64 MB: 413 too_large, and the parts form is named');
@unlink($big);
$lib = (int) one('SELECT library_id FROM folders WHERE id = :f', ['f' => $contracts]);
$used = (int) one('SELECT used_bytes FROM libraries WHERE id = :l', ['l' => $lib]);
pdo()->exec("UPDATE libraries SET quota_bytes = " . ($used + 100) . " WHERE id = $lib");
$r = api('POST', '/api/v1/upload', $km, ['file' => tmpfile_of(5000, 'q', 'over-quota.bin'), 'fields' => ['folder' => $contracts]]);
ok($r['code'] === 422 && $r['json']['error']['code'] === 'quota', 'over the library\'s quota: 422 quota');
pdo()->exec("UPDATE libraries SET quota_bytes = NULL WHERE id = $lib");
pdo()->exec("SELECT set_config('app.member_id', '26', false)"); one('SELECT dc_document_lock(:d, 26)', ['d' => $doc]);
$r = api('POST', '/api/v1/upload', $km, ['file' => $f2, 'fields' => ['folder' => $contracts, 'document' => $doc, 'conflict' => 'version']]);
ok($r['code'] === 423, 'a new version of a document someone else has locked: 423');
pdo()->exec("UPDATE documents SET locked_by = NULL, lock_expires_at = NULL, locked_at = NULL WHERE id = $doc");
ok((int) one("SELECT count(*) FROM activity_log WHERE action = 'upload.refused' AND source = 'api'") >= 1, 'a refusal is logged upload.refused (api)');

echo "3. The parts, through the mirror\n";
$parts = tmpfile_of(17 * 1048576 + 321, 'parts', 'archive-big.bin');
$r = api('POST', '/api/v1/upload/start', $km, ['json' => ['folder' => $contracts, 'filename' => 'archive-big.bin', 'byte_size' => filesize($parts)]]);
$st = $r['json'];
ok($r['code'] === 200 && $st['ok'] === true && $st['parts_total'] === 3 && $st['part_bytes'] === 8388608 && $st['session_id'] > 0, 'POST /upload/start: a session of 3 parts of 8 MB');
$sid = $st['session_id'];
$part = static fn (int $n): string => (string) file_get_contents($GLOBALS['parts'], false, null, ($n - 1) * 8388608, 8388608);
$r1 = api('PUT', "/api/v1/upload/$sid/1", $km, ['raw' => $part(1), 'headers' => ['Content-Type: application/octet-stream']]);
ok($r1['code'] === 200 && $r1['json']['part_no'] === 1 && $r1['json']['parts_done'] === 1, 'PUT /upload/{session}/1: part_no 1, parts_done 1');
$r = api('POST', "/api/v1/upload/$sid/finish", $km, ['json' => (object) []]);
ok($r['code'] === 422 && $r['json']['error']['code'] === 'missing_parts', 'finish with parts missing: 422 missing_parts');
ok(api('PUT', "/api/v1/upload/$sid/3", $km, ['raw' => $part(3), 'headers' => ['Content-Type: application/octet-stream']])['json']['parts_done'] === 2, 'part 3 before part 2: allowed');
$jr = api('PUT', "/api/v1/upload/$sid/2", $km, ['raw' => 'junk-bytes', 'headers' => ['Content-Type: application/octet-stream']]);
ok($jr['code'] === 422 && $jr['json']['error']['code'] === 'bad_part', 'a part of the wrong size: 422 bad_part, in words');
$rr = api('PUT', "/api/v1/upload/$sid/2", $km, ['raw' => $part(2), 'headers' => ['Content-Type: application/octet-stream']]);
ok($rr['code'] === 200 && $rr['json']['parts_done'] === 3, 'a repeat of part 2 overwrites it (resume): 3 of 3');
ok(api('PUT', "/api/v1/upload/$sid/1", $kp, ['raw' => 'x', 'headers' => ['Content-Type: application/octet-stream']])['code'] === 404, 'another person\'s session: 404');
ok(api('POST', "/api/v1/upload/$sid/finish", $kp, ['json' => (object) []])['code'] === 404, '...for finish too');
$r = api('POST', "/api/v1/upload/$sid/finish", $km, ['json' => (object) []]);
ok($r['code'] === 200 && $r['json']['ok'] === true && $r['json']['new_document'] === true && $r['json']['record_id'] > 0 && !isset($r['json']['location']), 'finish: 200 {ok, record_id the document, version_no}');
$pd = (int) $r['json']['record_id'];
ok(hash_file('sha256', $parts) === one('SELECT sha256 FROM document_versions WHERE document_id = :d', ['d' => $pd]) && (int) one('SELECT byte_size FROM documents WHERE id = :d', ['d' => $pd]) === filesize($parts), 'the assembled file is the file: sha256 and size');
$ev = last_event('document.upload');
ok($ev['source'] === 'api' && (int) $ev['token_id'] === $kid && (int) $ev['document_id'] === $pd, 'finish logs document.upload with source api and the key\'s token_id');
$r = api('POST', '/api/v1/upload/start', $km, ['json' => ['folder' => $contracts, 'filename' => 'archive-big.bin', 'byte_size' => 100]]);
ok($r['code'] === 409 && $r['json']['error']['code'] === 'name_taken' && $r['json']['error']['existing_document_id'] === $pd, 'start with a taken name: 409 name_taken {existing_document_id}');
ok(api('POST', '/api/v1/upload/start', $kb, ['json' => ['folder' => $pol, 'filename' => 'x.bin', 'byte_size' => 100]])['code'] === 403, 'start in a folder seen at view only: 403');
ok(api('POST', '/api/v1/upload/start', $km, ['json' => ['folder' => $contracts, 'filename' => 'zero.bin', 'byte_size' => 0]])['code'] === 422, 'a zero-byte start: 422');
$r = api('POST', '/api/v1/upload/start', $km, ['json' => ['folder' => $contracts, 'filename' => 'huge.bin', 'byte_size' => 9999999999999]]);
ok($r['code'] === 507 && $r['json']['error']['code'] === 'no_space', 'a 10 TB file: 507 no_space — no per-file ceiling since db/024, the store\'s room limits');
ok(api('GET', "/api/v1/upload/$sid/finish", $km)['code'] === 405 && api('GET', '/api/v1/upload/start', $km)['code'] === 405, 'the wrong method on the parts routes: 405');
ok(api('PUT', '/api/v1/upload/999999/1', $km, ['raw' => 'x', 'headers' => ['Content-Type: application/octet-stream']])['code'] === 404, 'an unknown session: 404');
finish();
